tool_args.command:
python3 -c "
import json
for exp in ['exp_029b_tcn_walker_s2_sigma02', 'exp_029d_tcn_walker_s3_sigma02']:
    path = f'/root/autodl-tmp/event-gated-adaptive-horizon/logdir/{exp}/metrics.jsonl'
    try:
        lines = open(path).readlines()
        last = json.loads(lines[-1])
        step = last.get('step', 'N/A')
        eval_r = last.get('eval/return', 'N/A')
        ve = last.get('ve_ratio', 'N/A')
        val_mean = last.get('value_mean', last.get('critic/value_mean', 'N/A'))
        print(f'{exp}: step={step}, eval={eval_r}, ve_ratio={ve}, value_mean={val_mean}')
        if '029b' in exp:
            print('  NVE trajectory:')
            for l in lines:
                d = json.loads(l)
                s = d.get('step', 0)
                if s % 10000 < 100 and 've_ratio' in d:
                    print(f'    step={s}: NVE={d[\"ve_ratio\"]:.3f}, eval={d.get(\"eval/return\", \"N/A\")}')
        if '029d' in exp:
            print('  NVE trajectory:')
            for l in lines:
                d = json.loads(l)
                s = d.get('step', 0)
                if s % 5000 < 100 and 've_ratio' in d:
                    print(f'    step={s}: NVE={d[\"ve_ratio\"]:.3f}, eval={d.get(\"eval/return\", \"N/A\")}')
    except Exception as e:
        print(f'{exp}: ERROR - {e}')
"
